CREATE TABLE IF NOT EXISTS market_intelligence.project_refresh_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), started_at timestamptz NOT NULL, finished_at timestamptz NOT NULL DEFAULT now(), trigger varchar(10) NOT NULL DEFAULT 'SCHEDULE', feeds_ok int NOT NULL DEFAULT 0, feeds_failed int NOT NULL DEFAULT 0, headlines_seen int NOT NULL DEFAULT 0, relevant int NOT NULL DEFAULT 0, inserted int NOT NULL DEFAULT 0, record_type varchar(10) NOT NULL DEFAULT 'FACT')
